const body = msg.payload;
const errors = [];

if (!body || typeof body !== 'object') {
    errors.push('Request body must be a JSON object');
} else {
    if (!body.id) errors.push('id is required');
    if (body.value === undefined) errors.push('value is required');
    if (body.value !== undefined && typeof body.value !== 'number') {
        errors.push('value must be a number');
    }
}

if (errors.length > 0) {
    msg.statusCode = 400;
    msg.payload = { success: false, errors: errors };
    return [null, msg];  // output 2: validation error
}

msg.validatedAt = new Date().toISOString();
return [msg, null];  // output 1: valid

const apiVersion = env.get('API_VERSION') || 'v1';

msg.payload = {
    success: true,
    api_version: apiVersion,
    received: {
        id: msg.payload.id,
        value: msg.payload.value,
        timestamp: msg.validatedAt
    },
    processed_at: new Date().toISOString()
};

msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
return msg;

msg.payload = {
    status: 'ok',
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    version: env.get('API_VERSION') || 'v1'
};
msg.statusCode = 200;
return msg;
